int main() {
    char ORD;
    int X = 0, Y = 0;
    int moviments = 0, errors = 0;
    do {
        cin >> ORD;
        switch (ORD) {
            case 'N':
            case 'n':
                Y++;
                moviments++;
                break;
            case 'S':
            case 's':
                Y--;
                moviments++;
                break;
            case 'E':
            case 'e':
                X++;
                moviments++;
                break;
            case 'O':
            case 'o':
                X--;
                moviments++;
                break;
            case 'F':
            case 'f':
                break;
            default:
                errors++;
        }
    } while (ORD != 'F' && ORD != 'f');
    cout << "Posicio final: (" << X << ", " << Y << ")" << endl;
    cout << "Moviments: " << moviments << endl;
    cout << "Ordres no valides: " << errors << endl;
    return 0;
}

