    for (int X = 1; X <= N; X++) {
        // nombre de xifres de X
        int K = 0;
        int aux = X;
        while (aux > 0) {
            K++;
            aux = aux / 10;
        }
        // suma de les xifres elevades a K
        int suma = 0;
        aux = X;
        while (aux > 0) {
            int xifra = aux % 10;
            int potencia = 1;
            for (int i = 0; i < K; i++) {
                potencia = potencia * xifra;
            }
            suma = suma + potencia;
            aux = aux / 10;
        }
        if (suma == X) {
            total++;
            int div = 1;
            for (int i = 1; i < K; i++) {
                div = div * 10;
            }
            cout << X << " =";
            bool primera = true;
            while (div > 0) {
                if (!primera) cout << " +";
                cout << " " << (X / div) % 10 << "^" << K;
                primera = false;
                div = div / 10;
            }
            cout << endl;
        }
    }
    cout << "Total: " << total << endl;
    return 0;
