int mcd(int a, int b) {
    while (b != 0) {
        int r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int mcm(int a, int b) {
    return a / mcd(a, b) * b;
}

int main() {
    int A, B;
    cin >> A >> B;
    while (A != 0 || B != 0) {
        cout << "mcd(" << A << "," << B << ") = " << mcd(A, B) << ", mcm(" << A << "," << B << ") = " << mcm(A, B) << endl;
        cin >> A >> B;
    }
    return 0;
}

#include <iostream>
