int invertit(int n) {
    int inv = 0;
    while (n > 0) {
        inv = inv * 10 + n % 10;
        n = n / 10;
    }
    return inv;
}

bool esCapicua(int n) {
    return invertit(n) == n;
}

int main() {
    int Y;
    cin >> Y;
    int maxEspera = -1, anyMax = 0;
    while (Y != 0) {
        int X = Y + 1;
        while (!esCapicua(X)) {
            X++;
        }
        int espera = X - Y;
        cout << Y << " -> " << X << " (" << espera << " anys)" << endl;
        if (espera > maxEspera) {
            maxEspera = espera;
            anyMax = Y;
        }
        cin >> Y;
    }
    cout << "Espera mes llarga: " << maxEspera << " anys (any " << anyMax << ")" << endl;
    return 0;
}
